{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 주차장 설치 및 관리 조례상 공영주차장 관리수탁자가 주차카드 발행·운용 업무를 위한 별도 법인을 설립할 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "관리수탁자는 주차카드를 발행·운용하는 경우 필요한 경우 주차카드의 발행 및 운용을 위한 법인을 설립·운영할 수 있다. 이는 서울특별시 주차장 설치 및 관리 조례 제12조 제2항에 따른 재량 규정이다.",
          "b_ids": "주차장:제12조제2항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "별도 법인을 설립할 경우 주차카드 발행·운용 업무에 대한 시장의 지도·감독에 응할 의무를 그 법인의 의무사항으로 포함해야 하는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "시장은 관리수탁자가 법인을 설립·운영하는 경우 주차카드 발행·운용 관련 사항에 대하여 이를 관리수탁자로 보아 지도·감독권을 행사할 수 있다. 관리수탁자는 법인에 대하여 시장의 지도·감독권 행사 대상이 되는 것과 시장의 지도·감독에 응할 의무가 있음을 법인의 의무사항으로 규정하는 등 시장의 지도·감독권이 원활히 행사될 수 있도록 하여야 한다.",
          "b_ids": "주차장:제12조제4항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
